import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Stamina and Reactive Combat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat/stamina-and-reactive-combat.md","filePath":"guide/combat/stamina-and-reactive-combat.md"}'),o={name:"guide/combat/stamina-and-reactive-combat.md"};function r(s,a,c,l,m,d){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="stamina-and-reactive-combat" tabindex="-1">Stamina and Reactive Combat <a class="header-anchor" href="#stamina-and-reactive-combat" aria-label="Permalink to &quot;Stamina and Reactive Combat&quot;">​</a></h1><ul><li><strong>Design status:</strong> Accepted automatic baseline; Proposed stamina and manual-input direction; unresolved conflict.</li><li><strong>Implementation:</strong> Inherited timing remains; no new attack key, fatigue or recovery system delivered.</li><li><strong>Availability:</strong> no new live behavior established here; current configuration not inspected.</li><li><strong>Verification:</strong> documentation reviewed 2026-10-08; no new playtest. Existing evidence is scoped in <a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">combat status</a>.</li></ul><h2 id="timing-without-broken-early-characters" tabindex="-1">Timing without broken early characters <a class="header-anchor" href="#timing-without-broken-early-characters" aria-label="Permalink to &quot;Timing without broken early characters&quot;">​</a></h2><p>Syrolands aims to reward movement, timing and reading an opponent while keeping ordinary combat approachable. The accepted baseline keeps normal attacks automatic. Proposed stat changes aim to keep low-DEX characters responsive; they are not live timing changes.</p><p>Stamina could make pursuit, heavy attacks, repeated pressure and recovery compete for resources. Weapon choice, technique and equipment burden could influence commitment and control. Exact costs and recovery times have not been selected.</p><h2 id="manual-attacks-are-a-proposal" tabindex="-1">Manual attacks are a proposal <a class="header-anchor" href="#manual-attacks-are-a-proposal" aria-label="Permalink to &quot;Manual attacks are a proposal&quot;">​</a></h2><p>A configurable key to request an attack is under consideration. Space is only an example, not a working control instruction. Requiring a keypress for every swing would conflict with the accepted automatic baseline; whether a manual mode is optional or replaces that baseline remains undecided.</p><p>Animations communicate action, but the server decides valid attacks and results. Accessibility, latency and client animation limits need evaluation before any input design is promised. Combat pressure could also affect magical Concentration under the separate Magic proposal.</p><p><a href="/Syrolands-Public/game-design/combat/stamina-and-reactive-combat.html">Full stamina and input specification</a> · <a href="/Syrolands-Public/guide/characters/stats.html">Stats Overview</a> · <a href="/Syrolands-Public/game-design/magic.html#concentration-under-pressure">Magic Concentration</a>.</p><p><a href="/Syrolands-Public/guide/combat/overview.html">Back to Combat overview</a></p>',10)])])}const h=e(o,[["render",r]]);export{p as __pageData,h as default};
